const orderId = $json.order_id?.trim().toUpperCase();

const orders = {
  "NS-10452": {
    status: "Shipped",
    carrier: "DHL",
    tracking_number: "DHL-84729301",
    estimated_delivery: "2026-10-08"
  },

  "NS-20891": {
    status: "Processing",
    carrier: null,
    tracking_number: null,
    estimated_delivery: "2026-10-10"
  },

  "NS-33721": {
    status: "Delivered",
    carrier: "FedEx",
    tracking_number: "FDX-58210493",
    estimated_delivery: "2026-10-03"
  }
};

const order = orders[orderId];

if (!order) {
  return {
    json: {
      success: false,
      order_id: orderId,
      message: "Order not found."
    }
  };
}

return {
  json: {
    success: true,
    order_id: orderId,
    ...order
  }
};
